program='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    centers = []
    for r in range(h):
        for c in range(w):
            if (grid[r][c] == 0 and 0 < r < h - 1 and 0 < c < w - 1
                    and grid[r - 1][c] == grid[r + 1][c] == grid[r][c - 1] == grid[r][c + 1] == 2):
                centers.append((r, c))

    for r in sorted({r for r, _ in centers}):
        cs = sorted(c for rr, c in centers if rr == r)
        for a, b in zip(cs, cs[1:]):
            for c in range(a + 2, b - 1):
                if out[r][c] == 0:
                    out[r][c] = 1

    for c in sorted({c for _, c in centers}):
        rs = sorted(r for r, cc in centers if cc == c)
        for a, b in zip(rs, rs[1:]):
            for r in range(a + 2, b - 1):
                if out[r][c] == 0:
                    out[r][c] = 1
    return out
'''
